  const modal=document.querySelector("#adminModal"),body=modal.querySelector("#adminBody");let password="",counts={schedule:0,players:0,drivers:0,locations:0,areas:0},profiles=[],records={schedule:[],players:[],drivers:[],locations:[],areas:[],assignments:[],eventDrivers:[]},kind="schedule",view="manage",editing=null,confirming=false,notice="",privateAddress=null,addressLogs=[];
  const close=()=>modal.remove();modal.querySelector(".close").addEventListener("click",close);modal.addEventListener("click",event=>{if(event.target===modal)close()});
  const adminApi=async(method="GET",payload)=>{const response=await fetch(ADMIN_API,{method,headers:{"content-type":"application/json","x-admin-password":password},body:payload?JSON.stringify(payload):undefined});const result=await response.json();if(!response.ok)throw new Error(result.error||"Admin request failed");return result};
  const apply=result=>{counts=result.counts;profiles=result.profiles||[];records=result.records||records};
  const list=()=>kind==="parents"?profiles:records[kind];
