    body.querySelector("[data-remove]")?.addEventListener("click",async()=>{try{apply(await adminApi("POST",{action:"delete_record",kind,id:editing.id}));editing=null;confirming=false;notice="Record removed.";if(profile?.approved)await refresh();showTools()}catch(error){notice=error.message;showTools()}});
